import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BjkiRu3Q.js";const h=JSON.parse('{"title":"Local drafts and recovery","description":"","frontmatter":{},"headers":[],"relativePath":"websites/draft-storage.md","filePath":"websites/draft-storage.md"}'),s={name:"websites/draft-storage.md"};function i(n,e,c,l,d,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="local-drafts-and-recovery" tabindex="-1">Local drafts and recovery <a class="header-anchor" href="#local-drafts-and-recovery" aria-label="Permalink to &quot;Local drafts and recovery&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release — source-reviewed draft</p><p>TransferBook+ v0.7.9 source baseline. Availability depends on installed release, permissions and configuration. Live publication is not established by this guide.</p></div><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Preserve work before switching company, browser, device or operating mode. Website Studio in this source baseline stores drafts locally, scoped to company and operating mode.</p><h2 id="save-and-recover" tabindex="-1">Save and recover <a class="header-anchor" href="#save-and-recover" aria-label="Permalink to &quot;Save and recover&quot;">​</a></h2><ol><li>Confirm the correct company context and selected website.</li><li>Save your draft using the available studio controls and verify the save outcome.</li><li>Export a portable website package and keep a separate backup.</li><li>Use History to inspect earlier local snapshots and restore a suitable revision when necessary.</li><li>Before changing browser or mode, export first. Import into the intended authorized workspace and validate again.</li></ol><h2 id="expected-result" tabindex="-1">Expected result <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Expected result&quot;">​</a></h2><p>The saved draft remains local to its browser and scope. Local storage is not encryption, server-side backup or cross-device synchronization.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p>If storage is unavailable, treat saving as unsuccessful and export where possible before closing the page. Earlier unscoped drafts are not automatically migrated across companies. Recover them from their original context using export/import, not by copying storage keys. See <a href="./portable-packages.html">portable packages</a>.</p><h2 id="autosave-and-workspace-backup-in-v0-7-10" tabindex="-1">Autosave and workspace backup in v0.7.10 <a class="header-anchor" href="#autosave-and-workspace-backup-in-v0-7-10" aria-label="Permalink to &quot;Autosave and workspace backup in v0.7.10&quot;">​</a></h2><p><strong>Status: source-reviewed staging release.</strong> Autosave and recovery are isolated by company and operating mode, as are saved drafts. Autosave does not replace the main saved workspace.</p><ol><li>If the recovery banner offers an unsaved draft, check the site and recovery timestamp. Restore only the intended draft, then use Save Draft and verify the outcome.</li><li>In History, inspect storage usage and validation status. Export a full workspace backup (<code>.json</code>) for independent safekeeping, in addition to portable site exports.</li><li>To restore a workspace backup, use the compatible import workflow in its authorized scope. Review the recovered sites before saving. Cross-company backup restrictions must not be bypassed.</li><li>If storage quota or corrupted local data causes a warning, preserve any available export before cleanup. Revision history may be pruned when quota is exceeded; do not assume all earlier revisions survive.</li></ol><p>Browser recovery is not server backup or cross-device synchronization.</p>',14)])])}const v=a(s,[["render",i]]);export{h as __pageData,v as default};
